# ══════════════════════════════ Startup ══════════════════════════════
if __name__ == "__main__":
    os.environ.setdefault("QT_QUICK_CONTROLS_STYLE", "Basic")
    # ── Crash safety (user request: the app must never die with a sudden Segmentation fault) ──
    # 1) Chromium flags (owner report: the GL-gate fast path was already chosen yet the chart
    #    stayed heavy and the terminal still stormed with "Failed to create GLES3 context" /
    #    "kFatalFailure: Failed to create shared context for virtualization"). Root cause: the
    #    old software-forced flags (--disable-gpu*) made Chromium keep REQUESTING GPU contexts
    #    it could never create, every failed attempt burning CPU. Hardware GPU is now the
    #    default — the context succeeds, the retry storm and the heaviness go away, and the
    #    --disable-gpu* / --disable-accelerated-2d-canvas / CalculateNativeWinOcclusion /
    #    --disable-dev-shm-usage flags are all gone. Flags are APPENDED to any existing value,
    #    so clear the stale terminal variable before relaunching (cmd: set QTWEBENGINE_CHROMIUM_FLAGS=
    #    / PowerShell: Remove-Item Env:QTWEBENGINE_CHROMIUM_FLAGS / linux-mac: unset …).
    _soft = bool(os.environ.get("BADI_SHOTS")) or (
        sys.platform.startswith("linux") and not os.environ.get("DISPLAY"))
    _flags = [f for f in os.environ.get("QTWEBENGINE_CHROMIUM_FLAGS", "").split() if f]
    for _fl in ("--no-sandbox", "--ignore-gpu-blocklist", "--enable-gpu-rasterization"):
        if _fl not in _flags:
            _flags.append(_fl)
    if sys.platform.startswith("win") and not any(f.startswith("--use-angle") for f in _flags):
        _flags.append("--use-angle=d3d11")
    if _soft:
        # حاويات/اختبار بدون شاشة فقط
        for _fl in ("--disable-gpu", "--enable-unsafe-swiftshader"):
            if _fl not in _flags:
                _flags.append(_fl)
    os.environ["QTWEBENGINE_CHROMIUM_FLAGS"] = " ".join(_flags)
    if os.environ.get("BADI_SHOTS"):
        print("BADIFLAGS " + os.environ["QTWEBENGINE_CHROMIUM_FLAGS"], flush=True)
    # 2) A crash log: if anything fatal still happens, the Python stack lands in
    #    ~/.badi-charts/crash.log with a timestamp — send it and the exact line is found.
    try:
        import faulthandler as _fh
        os.makedirs(CFG_DIR, exist_ok=True)
        _fh.enable(file=open(os.path.join(CFG_DIR, "crash.log"), "ab", buffering=0))
    except Exception:
        pass

    def _exc_hook(t, v, tb):
        try:
            import traceback
            with open(os.path.join(CFG_DIR, "crash.log"), "ab") as f:
                f.write(("\n[%s] Python exception\n" % datetime.now().isoformat()).encode())
                traceback.print_exception(t, v, tb, file=f)
        except Exception:
            pass
    sys.excepthook = _exc_hook
    # 3) Ctrl+C / SIGTERM close the app gracefully instead of dying mid-render.
    try:
        import signal as _signal
        def _sig_quit(*_a):
            try:
                app.quit()
            except Exception:
                pass
        _signal.signal(_signal.SIGINT, _sig_quit)
        _signal.signal(_signal.SIGTERM, _sig_quit)
    except Exception:
        pass
    QtWebEngineQuick.initialize()
    app = QGuiApplication(sys.argv)
    app.setOrganizationName("BadiCharts")
    app.setApplicationName("BadiChartsStudio")
    app.setWindowIcon(make_app_icon())   # App logo in the title bar and taskbar
    engine = QQmlApplicationEngine()
    backend = Backend()
    engine.rootContext().setContextProperty("backend", backend)
    engine.rootContext().setContextProperty("dbgShotDir", os.environ.get("BADI_SHOTS", ""))
    theme_json = json.dumps({"dark": backend.dark, "c": (DARK if backend.dark else LIGHT),
                             "lang": backend.lang})
    engine.rootContext().setContextProperty("webUrl",
                                            ensure_web_files(backend.boot_files_json(), theme_json))
    engine.rootContext().setContextProperty("splashUrl", SPLASH_URL)
    engine.loadData(QML.encode("utf-8"))
    if not engine.rootObjects():
        os._exit(-1)
    rc = app.exec()
    # 4) Teardown (user request: no crash on close). Destroying the QML engine while
    #    Chromium helper threads are still alive is a classic exit-time "Segmentation
    #    fault". Every app file (config, signals, indicators) is written synchronously
    #    the moment it changes, so a hard exit here is safe and removes that entire
    #    crash class. The short grace period gives Chromium one last moment to flush
    #    its storage (chart colors and page settings live in localStorage).
    try:
        backend.stop_all()
    except Exception:
        pass
    try:
        time.sleep(1.0)
    except Exception:
        pass
    try:
        sys.stdout.flush()
        sys.stderr.flush()
    except Exception:
        pass
    os._exit(rc)


# ==========================================================================
#  End of code — the last line that runs is launching the app from PART 3 above.
#  END OF SOURCE — the app boots from the __main__ block of PART 3.
# ==========================================================================
